from pathlib import Path
import json,re,statistics
base=Path('.work/toy-character/dino')
rows=json.loads((base/'summary.json').read_text());perf=json.loads((base/'performance.json').read_text());assets=json.loads((base/'assets.json').read_text())
verify=(base/'verify.log').read_text();passed=re.findall(r'(\d+) passed[^\n]*',verify)
lines=['# 恐竜のいる野原の確認記録','', '恐竜6体とヤシ・シダ・低い草・丸い岩へ替え、キャラを横長で約38%、縦長で約33%の高さにした。30°を推す。50°は横へ進む印象が強いが、目と眼鏡は30°の方が見やすい。','', '[静止画の比較](stills.png) / [脚の連続写真](legs-desktop.png)','']
for name in ['desktop','mobile']:
 lines.append(f"- {name}: [30°の動画]({name}-30.webm)、[50°の動画]({name}-50.webm)、[30°のstrip]({name}-30-strip.png)、[50°のstrip]({name}-50-strip.png)")
lines+=['','## 素材と見た目','', '恐竜は作者のAnimated Dinosaur PackのBlendファイルからBlender 5.2.2で変換し、WalkとIdleだけを残した。Velociraptorは歩きの末尾の静止区間を除き、0〜28フレームを使う。歩調は1.6倍にし、足の後退量から前進量を求めるので、足の運びと速さは一致する。四足の前後脚の歩幅の違いは接地中だけ二関節で補正する。','', 'ヤシはUltimate Nature PackのPalmTree_1とPalmTree_3、シダ・草・岩はStylized Nature MegaKit StandardのFern_1、Grass_Common_Short、Rock_Medium_1を選んだ。いずれもCC0。作者のitch.io公式配布から取得した。Google Driveはダウンロード上限の応答だったため、その控えも残した。','', '色はくすんだ緑、茶、灰色とし、恐竜は元の部位ごとの明暗を残した。画像を使わず、roughnessは0.94〜0.95。黒い輪郭線は付けていない。キャラのGLBとwalk.tsは以前の保存版とSHA-256が一致する。','', '恐竜は6種類を15秒間隔で順番に出し、大きさの順を保って、キャラより奥を歩かせる。Apatosaurusはさらに遠くへ置く。木と小物は置く距離で頭・胴体を避け、重なりに応じた非表示や透明化は行わない。','', '配布物・ページ・ライセンス・SHA-256は [vendor/manifest.json](vendor/manifest.json)、部品の構成は [assets.json](assets.json) にある。','', '| GLB | 三角形 | 材質 | 骨 | 画像 | KiB |','| --- | ---: | ---: | ---: | ---: | ---: |']
for a in assets['assets']:lines.append(f"| {a['name']} | {a['triangles']:.0f} | {a['materials']} | {len(a['bones'][0]) if a['bones'] else 0} | {len(a['images'])} | {a['bytes']/1024:.1f} |")
lines+=['',f"合計は{assets['totalBytes']:,} bytes（{assets['totalBytes']/1048576:.3f} MiB）。2 MiB以内に収まった。glTF Validatorは全11本でエラー0。恐竜各1件のnon-root skinned-node警告があり、Chromeで親の移動・回転・縮尺とスキニングの追従を確認した。",'', '## 3分間の記録','', '横長の30°・50°は各181秒の実時間で記録した。全4条件について、最終コードを1/60秒刻みで180秒進める補足検査も行った。縦長の動画は各66秒で、元の実時間記録は各69秒ある。','', '実時間の両角度で、膝は0〜40°、太ももは前22.87°・後ろ23.41°。一歩の中央の足の高さは31.3〜34.5 mm。支持接地点の滑りは0.001 mm未満、靴底周辺の変形は最大0.53 mmだった。','', '| 実時間・横長 | 30° | 50° |','| --- | ---: | ---: |']
a,b=rows[:2]
for label,values in [('区間の付け替え',[a['exchanges'],b['exchanges']]),('原点の付け替え',[a['rebases'],b['rebases']]),('同じ配置の連続',[a['repeats'],b['repeats']]),('恐竜の出現',[a['visibleAppearances'],b['visibleAppearances']]),('恐竜の種類',[len(a['visibleTypes']),len(b['visibleTypes'])]),('出現間隔の最大（秒）',[round(a['maxAppearanceGapSeconds'],2),round(b['maxAppearanceGapSeconds'],2)]),('恐竜の足裏の滑り最大（mm）',[round(a['dinosaurSlipMm'],3),round(b['dinosaurSlipMm'],3)]),('木の最小 / 中央値',[f"{r['trees']['min']} / {r['trees']['median']}" for r in [a,b]]),('物の最小 / 中央値 / 最大',[f"{r['objects']['min']} / {r['objects']['median']} / {r['objects']['max']}" for r in [a,b]]),('頭・胴体との重なり',[a['overlapFrames'],b['overlapFrames']]),('ヒープ開始→終了（MiB）',[f"{r['heapStartBytes']/1048576:.2f} → {r['heapEndBytes']/1048576:.2f}" for r in [a,b]]),('終了後GC（MiB）',[f"{r['heapAfterGcBytes']/1048576:.2f}" for r in [a,b]])]:lines.append(f'| {label} | {values[0]} | {values[1]} |')
lines+=['', '重なりは計測開始後の増分。読み込み時からの累積値とは分けている。最終コードでは画角が整う前の描画を止め、補足検査も全4条件で重なり0回だった。ヒープの値には開発用の計測配列の保持を含む。物と木の数はモデルの境界を投影して数え、影と地面は除外した。','', '| 180秒の補足検査 | 木の最小 / 中央値 | 物の最小 / 中央値 / 最大 | 重なり |','| --- | --- | --- | ---: |']
for name in ['desktop','mobile']:
 for angle in [30,50]:
  m=json.loads((base/f'simulation-{name}-{angle}.json').read_text())['metrics'];s=m['scenery'];lines.append(f"| {name} {angle}° | {min(m['treeCounts'])} / {statistics.median(m['treeCounts']):g} | {min(m['objectCounts'])} / {statistics.median(m['objectCounts']):g} / {max(m['objectCounts'])} | {s['overlapFrames']} |")
lines+=['','## 速さと動作確認','', 'Chrome、ANGLE Metal、Apple M5 Max。CPUを4倍遅くし、各10秒のrequestAnimationFrame間隔を測った。撮影・補足検査・E2Eを同時に動かしていない状態で測定した。','', '| 大きさ | 角度 | DPR | 中央値 ms | P95 ms |','| --- | ---: | ---: | ---: | ---: |']
for r in perf:lines.append(f"| {r['w']}×{r['h']} | {r['angle']}° | {r['dpr']} | {r['medianMs']:.1f} | {r['p95Ms']:.1f} |")
lines+=['', '動きを減らす設定、途中での設定変更、押した方向への注視、実際に恐竜を押したときの個体の選択、歩行再開、iframeの画面外での停止と再開、非表示イベントによる停止と再開を確認した。非表示タブの検査はheadless Chromeのvisibilitychange経路へhiddenを渡す方法を使った。','', f"`pnpm verify --config .work/toy-character/walk/chrome.config.ts --output .work/toy-character/dino/verify-results --workers 4`: {passed[-1]+'件成功' if passed and not re.search(r'\d+ failed',verify) else 'verify.logを参照（全体検証を再実行中）'}。",'', '画像は静止画の比較、足の連続写真、動画4本の全stripを開いて確認した。WebMはChromeのvideo要素でも開き、停止前後と終盤を再生して確認し、4本とも66秒を最後まで再生した。','', '## 残る点と仮定','', '- 縦長30°は180秒の補足検査で一時11個になり、目安の上限10個を1個超えた。','- 地質時代と実寸は指定がないため、複数時代の恐竜と植物が同じ野原にいる、おもちゃの相対的な大きさとして組んだ。','- 「0.7秒を1/12秒ごと」は、0〜0.667秒の9コマ（約0.7秒）とした。','- 非表示タブの検査はイベント経路の模擬で、実機スマホの熱・電力条件は測っていない。','- 画角の最終選択は作者に委ね、初期値は指定どおり30°のままにした。','', '開発サーバーの4410番は止めていない。コミットはしていない。','']
(base/'README.md').write_text('\n'.join(lines))
